<style>
.round-f {
  animation: rotate-f 5s linear infinite;
}

.round-b {
  animation: rotate-b 5s linear infinite;
}

@keyframes rotate-f {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes rotate-b {
  from { transform: rotate(0deg); }
  to { transform: rotate(-360deg); }
}
</style>
